void test_mask_inout(struct C *p) {
  asm("" : "+k"(*p));
}

// An output tied to a larger input is returned as a vector of the input's size.
// CHECK-LABEL: define dso_local void @test_mask_tied_int(
// CHECK-SAME: ptr noundef [[P:%.*]], i32 noundef [[X:%.*]]) #[[ATTR1:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[P_ADDR:%.*]] = alloca ptr, align 8
// CHECK-NEXT:    [[X_ADDR:%.*]] = alloca i32, align 4
// CHECK-NEXT:    store ptr [[P]], ptr [[P_ADDR]], align 8
// CHECK-NEXT:    store i32 [[X]], ptr [[X_ADDR]], align 4
// CHECK-NEXT:    [[TMP0:%.*]] = load ptr, ptr [[P_ADDR]], align 8
// CHECK-NEXT:    [[TMP1:%.*]] = load i32, ptr [[X_ADDR]], align 4
// CHECK-NEXT:    [[TMP2:%.*]] = bitcast i32 [[TMP1]] to <32 x i1>
// CHECK-NEXT:    [[TMP3:%.*]] = call <32 x i1> asm "", "=k,0,~{dirflag},~{fpsr},~{flags}"(<32 x i1> [[TMP2]]) #[[ATTR2]], !srcloc [[META3:![0-9]+]]
// CHECK-NEXT:    [[TMP4:%.*]] = bitcast <32 x i1> [[TMP3]] to i32
// CHECK-NEXT:    [[TMP5:%.*]] = trunc i32 [[TMP4]] to i16
// CHECK-NEXT:    store i16 [[TMP5]], ptr [[TMP0]], align 1
// CHECK-NEXT:    ret void
//
void test_mask_tied_int(struct C *p, int x) {
  asm("" : "=k"(*p) : "0"(x));
}

